pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 warp, uint256 roll) public {
        vm.assume(actor != address(0));
        vm.warp(warp);
        vm.roll(roll);

        uint256 potBefore = c.pot();
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.play{value: 10}();

        uint256 potAfter = c.pot();
        // General rule: a play either deposits exactly TICKET_AMOUNT (10) into pot,
        // or wins and resets pot to 0.
        assertTrue(potAfter == potBefore + 10 || potAfter == 0);
    }
}

