pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint constant TICKET = 10;

    receive() external payable {}

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 n, uint256 seed) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        n = bound(n, 1, 8);
        vm.deal(actor, TICKET * n);
        vm.assume(seed > 0);

        uint256 deposits = 0;
        for (uint256 i = 0; i < n; i++) {
            vm.warp(seed + i);
            vm.prank(actor);
            c.play{value: TICKET}();
            deposits += TICKET;
        }

        assertTrue(c.pot() <= deposits);
    }
}

