pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 warpTime) public {
        // keep the actor a plain, non-degenerate EOA (no code, not a precompile/zero)
        vm.assume(actor > 0x10000 && actor.code.length == 0);
        vm.assume(warpTime < 2**64);
        vm.warp(warpTime); // shifts keccak randomness so the fuzzer explores both win and lose branches

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.play{value: 10}();

        // General rule: the pot is always a whole number of tickets
        // (a losing play adds exactly TICKET_AMOUNT; a winning play resets it to 0).
        assertTrue(c.pot() % 10 == 0);
    }
}

