pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    receive() external payable {}

    function testFuzz_property(uint256 seed, address actor) public {
        // actor must be a plain EOA that can hold and receive ETH
        vm.assume(actor != address(0) && actor.code.length == 0);
        // search warp seeds so the fuzzer can hit random == 0 (a win) or random == 1 (a loss)
        vm.warp(seed);

        // ticket is fixed at 10 wei; fund the player and play
        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        // GENERAL RULE: pot is always a multiple of the ticket amount (10).
        // Reference: loss -> pot grows by 10; win -> paid out fully and reset to 0. Always multiple of 10.
        // Mutant: after a win pot is set to 1, which is NOT a multiple of 10.
        assertTrue(c.pot() % 10 == 0, "pot must remain a multiple of TICKET_AMOUNT");
    }
}

