pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 warp, uint256 roll, address actor) public {
        warp = bound(warp, 1, 2 ** 64);
        roll = bound(roll, 0, 2 ** 64);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.warp(warp);
        vm.roll(roll);

        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        // Universal rule: after any play, the pot is even (0 on a win, 10 on a loss).
        // The mutant sets pot = FEE_AMOUNT = 1 on a win (or 11 after a losing-then-winning
        // sequence is impossible here, but 1 is odd), breaking parity.
        assertTrue(c.pot() % 2 == 0);
    }
}

