pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0); // EOA recipient so transfer succeeds in both versions
        vm.warp(ts);
        vm.roll(1);

        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();

        uint256 r = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
        assertTrue(
            (r == 0 && c.pot() == 0) || (r == 1 && c.pot() == 10),
            "pot must equal 0 on win and 10 on loss"
        );
    }
}

