contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function test(uint amount) public {
        require(address(this).balance >= 3 * amount);

        uint b0 = address(this).balance;
        bool ok1 = c.play{value: amount}();
        require(ok1);
        uint b1 = address(this).balance;

        bool ok2 = c.play{value: amount}();
        require(ok2);
        uint b2 = address(this).balance;

        bool ok3 = c.play{value: amount}();
        require(ok3);
        uint b3 = address(this).balance;

        // If no payout was ever received across the three plays,
        // every play lost, so the pot must have accumulated all three stakes.
        assert(!(b1 == b0 && b2 == b1 && b3 == b2) || c.pot() == 3 * amount);
    }
}

